const defaultProfile={page:'overview',goal:'Data Analyst',hours:'3–5 hours',project:'',skills:{Excel:78,SQL:55,Python:42,Storytelling:64},journey:42,plan:null,userId:localStorage.getItem('codevenjar-user-id')||`CV-${new Date().getFullYear()}-${Math.random().toString(36).slice(2,8).toUpperCase()}`,status:'Learning',records:[],enrollments:[],payments:[],selectedCourse:null,aiMessages:[]};
const saved=JSON.parse(localStorage.getItem('codevenjar-profile')||'null');
const state={...defaultProfile,...(saved||{}),skills:{...defaultProfile.skills,...(saved?.skills||{})}};
const nav=[['overview','⌂','Overview'],['assessment','◈','Skill assessment'],['roadmap','↗','My roadmap'],['assignments','✓','Assignments'],['courses','▤','Courses'],['records','▥','My records'],['status','●','Current status'],['ai','✦','AI support'],['mentors','♧','Mentors'],['portfolio','▣','Portfolio']];
const templates={
 'Data Analyst':{skills:['Excel','SQL','Python','Storytelling'],projects:[['Retail Sales Dashboard','SQL · Power BI','3–4 hours'],['Customer Churn Story','Python · SQL','5–6 hours'],['Marketing Performance Report','Excel · Storytelling','4 hours']]},
 'Web Developer':{skills:['HTML/CSS','JavaScript','React','Git'],projects:[['Responsive Portfolio','HTML/CSS · Git','3–4 hours'],['Full-stack Task Board','React · API','6–8 hours'],['E-commerce Product Page','React · GitHub','5 hours']]},
 'AI Engineer':{skills:['Python','Math & Statistics','Machine Learning','LLM APIs'],projects:[['Student Score Predictor','Python · ML','4–5 hours'],['RAG Study Assistant','Python · LLM API','6–8 hours'],['Resume Feedback Agent','Prompting · API','5 hours']]}
};
const app=document.querySelector('#app');
function persist(){localStorage.setItem('codevenjar-profile',JSON.stringify(state));localStorage.setItem('codevenjar-user-id',state.userId)}
function addRecord(type,title,detail){state.records.unshift({id:`REC-${Date.now()}`,type,title,detail,at:new Date().toISOString()});state.records=state.records.slice(0,50);persist()}
const courses=[
 {id:'excel-starter',title:'Excel Starter for Career Beginners',mode:'Recorded',level:'Beginner',duration:'2 weeks',price:0,description:'Learn cells, formulas, sorting, filters and a simple career-ready dashboard.',skills:['Excel','Data basics'],outcome:'Complete your first mini dashboard and receive a free completion record.',notes:['Excel formulas cheat sheet','Practice sales dataset','Dashboard checklist'],access:'Instant recorded access'},
 {id:'sql-foundations',title:'SQL Foundations for Analysts',mode:'Live',level:'Beginner',duration:'4 weeks',price:499,description:'Queries, joins, filtering, aggregation and real interview-style datasets.',skills:['SQL','Data cleaning'],outcome:'Build a strong SQL base and complete 20 practice challenges.',notes:['SQL joins notes','Weekly query workbook','Live class recordings'],access:'Live class: Tuesday & Thursday, 7:00 PM IST'},
 {id:'power-bi',title:'Power BI Business Dashboard',mode:'Live',level:'Intermediate',duration:'3 weeks',price:799,description:'Turn raw business data into an interactive dashboard and clear insights.',skills:['Power BI','Storytelling'],outcome:'Publish one portfolio-ready executive dashboard.',notes:['Dashboard wireframe','DAX quick reference','Business storytelling notes'],access:'Live class: Saturday, 11:00 AM IST'},
 {id:'python-data',title:'Python for Data Projects',mode:'Recorded',level:'Intermediate',duration:'6 weeks',price:999,description:'Pandas, visualisation, notebooks and a complete end-to-end analytics project.',skills:['Python','Pandas'],outcome:'Ship a reproducible Python case study for your portfolio.',notes:['Pandas notebook','Cleaning checklist','Project rubric'],access:'Instant recorded access'},
 {id:'web-starter',title:'Web Developer Starter Track',mode:'Recorded',level:'Beginner',duration:'6 weeks',price:899,description:'HTML, CSS, JavaScript, Git and a responsive portfolio website.',skills:['HTML/CSS','JavaScript','Git'],outcome:'Deploy a polished personal portfolio website.',notes:['HTML/CSS reference','Git commands sheet','Portfolio checklist'],access:'Instant recorded access'}
];
function courseById(id){return courses.find(c=>c.id===id)}
const mentors=[
 {id:'m1',name:'Neha Sharma',role:'Senior Data Analyst',specialty:'SQL · Power BI · Interviews',rating:'4.9',slots:'Tue & Thu · 7:00 PM',bio:'Helps students turn dashboards into strong portfolio stories.'},
 {id:'m2',name:'Arjun Mehta',role:'Analytics Engineer',specialty:'Python · Data Projects',rating:'4.8',slots:'Wed · 8:00 PM',bio:'Guides beginners through practical Python and case-study projects.'},
 {id:'m3',name:'Riya Kapoor',role:'Career Coach',specialty:'Resume · LinkedIn · Mock interviews',rating:'4.9',slots:'Sat · 11:00 AM',bio:'Helps learners present their skills clearly to internship recruiters.'}
];
const assignments=[
 {id:'a1',title:'SQL Gap Check',topic:'SQL',difficulty:'Beginner',time:'20 min',prompt:'Write a query that returns total sales by product category using GROUP BY.',answer:'Use SELECT category, SUM(sales) and GROUP BY category.',done:false},
 {id:'a2',title:'Dashboard Insight',topic:'Storytelling',difficulty:'Beginner',time:'15 min',prompt:'Write two business insights from a dashboard showing falling sales and rising returns.',answer:'Mention the trend, evidence and one recommended action.',done:false},
 {id:'a3',title:'Python Data Cleaning',topic:'Python',difficulty:'Intermediate',time:'30 min',prompt:'List three steps you would take before analysing a CSV with missing values.',answer:'Profile missingness, choose an imputation/drop strategy and validate the cleaned data.',done:false}
];
function mentorPage(){return header('Connect & grow','Mentor network','Choose a mentor, see their availability and book an office hour.')+`<div class="grid content-grid"><div class="grid">${mentors.map(m=>`<div class="card"><div class="card-heading"><h3>${m.name}</h3><span class="pill">★ ${m.rating}</span></div><strong>${m.role}</strong><p style="color:var(--muted);line-height:1.5">${m.bio}</p><div style="display:flex;gap:8px;flex-wrap:wrap;margin:12px 0"><span class="tag">${m.specialty}</span><span class="tag">${m.slots}</span></div><button class="primary mentor-book" data-mentor="${m.id}">Book mentor session →</button></div>`).join('')}</div><div class="card"><div class="card-heading"><h3>My bookings</h3><span class="tag">${state.mentorBookings?.length||0}</span></div>${state.mentorBookings?.length?state.mentorBookings.map(b=>`<div class="task"><div><p>${b.mentor}</p><small>${b.slot} · ${b.status}</small></div><span class="tag">Booked</span></div>`).join(''):'<p style="color:var(--muted)">Choose a mentor to create your first booking.</p>'}</div></div>`+(state.selectedMentor?mentorModal(mentors.find(m=>m.id===state.selectedMentor)):'')}
function mentorModal(m){return `<div class="modal-backdrop"><div class="card payment-modal"><div class="card-heading"><h3>Book ${m.name}</h3><button class="icon-btn" id="close-mentor">×</button></div><p style="color:var(--muted)">${m.role} · ${m.specialty}</p><form id="mentor-form" class="form-grid"><div class="field full"><label>Choose a slot</label><select id="mentor-slot"><option>${m.slots}</option><option>Next available slot</option></select></div><div class="field full"><label>What do you need help with?</label><textarea id="mentor-note" rows="3" placeholder="Example: review my SQL dashboard project"></textarea></div><div class="field full"><button class="primary" type="submit">Confirm mentor booking</button></div></form></div></div>`}
function assignmentsPage(){return header('Practice to prove','Assignments','Small practical tasks connected to your roadmap. Complete them to build your record.')+`<div class="grid content-grid"><div class="grid">${assignments.map(a=>`<div class="card"><div class="card-heading"><h3>${a.title}</h3><span class="tag">${a.time}</span></div><p style="color:var(--muted)">${a.prompt}</p><div style="display:flex;gap:8px;margin:12px 0"><span class="tag">${a.topic}</span><span class="tag">${a.difficulty}</span></div><div class="result"><strong>Hint:</strong> ${a.answer}</div><button class="primary assignment-done" data-assignment="${a.id}" ${a.done?'disabled':''}>${a.done?'Completed ✓':'Mark assignment complete'}</button></div>`).join('')}</div><div class="card"><div class="card-heading"><h3>Assignment progress</h3><span class="pill">${assignments.filter(a=>a.done).length}/${assignments.length}</span></div><p style="color:var(--muted);line-height:1.6">Assignments are linked to your skill gaps. Complete one after each roadmap module and save the result in My records.</p><button class="secondary" data-page="records">View records</button></div></div>`}
function portfolioPage(){const p=state.portfolio||{name:'Abhi Kumar',headline:'Aspiring Data Analyst',bio:'I turn messy data into clear business insights.',location:'India',skills:Object.keys(state.skills).join(' · '),project:'Retail Sales Dashboard'};return header('Show your proof','My portfolio','Build a shareable profile from your skills, projects and completed learning.')+`<div class="grid content-grid"><div class="card"><div class="card-heading"><h3>Edit profile</h3><span class="tag">Saved locally</span></div><form id="portfolio-form" class="form-grid"><div class="field full"><label>Name</label><input id="profile-name" value="${p.name}" required /></div><div class="field full"><label>Professional headline</label><input id="profile-headline" value="${p.headline}" required /></div><div class="field full"><label>Short bio</label><textarea id="profile-bio" rows="3">${p.bio}</textarea></div><div class="field"><label>Location</label><input id="profile-location" value="${p.location}" /></div><div class="field"><label>Featured project</label><input id="profile-project" value="${p.project}" /></div><div class="field full"><button class="primary" type="submit">Save portfolio profile</button></div></form></div><div class="card portfolio-preview"><div class="pill">CODEVENJAR PORTFOLIO</div><div class="avatar" style="margin-top:18px">${p.name.split(' ').map(x=>x[0]).join('').slice(0,2)}</div><h2>${p.name}</h2><h3>${p.headline}</h3><p style="color:var(--muted);line-height:1.6">${p.bio}</p><p><strong>Skills</strong><br/><span style="color:var(--cyan)">${p.skills||Object.keys(state.skills).join(' · ')}</span></p><p><strong>Featured project</strong><br/>${p.project}</p><span class="tag">${state.goal} track · User ${state.userId}</span></div></div>`}
function statusPage(){return header('Live learner record','Current status','Your account, progress and enrollment status in one place.')+`<div class="grid stats"><div class="card stat"><span class="label">User ID</span><strong style="font-size:19px">${state.userId}</strong><span class="delta">Permanent learner ID</span></div><div class="card stat"><span class="label">Account status</span><strong>${state.status}</strong><span class="delta">Updated automatically</span></div><div class="card stat"><span class="label">Enrollments</span><strong>${state.enrollments.length}</strong><span class="delta">Courses purchased</span></div><div class="card stat"><span class="label">Records</span><strong>${state.records.length}</strong><span class="delta">Activity history</span></div></div><div class="card"><div class="card-heading"><h3>Journey health</h3><span class="pill">${state.plan?'Personalized':'Assessment pending'}</span></div><p style="color:var(--muted);line-height:1.6">Your current track is <strong style="color:var(--text)">${state.goal}</strong>. ${state.plan?`Priority gaps: ${state.plan.focus.join(', ')}.`:'Complete the skill assessment to generate your first roadmap.'}</p><button class="primary" data-page="${state.plan?'roadmap':'assessment'}">${state.plan?'Open my roadmap':'Start assessment'} →</button></div>`}
function recordsPage(){return header('Learning history','My records','Every assessment, roadmap update, enrollment and payment is recorded here.')+`<div class="card"><div class="card-heading"><h3>Activity records</h3><span class="tag">${state.records.length} saved</span></div>${state.records.length?state.records.map(r=>`<div class="task"><div><p>${r.title}</p><small>${r.type} · ${r.detail}</small></div><span class="tag">${new Date(r.at).toLocaleDateString('en-IN')}</span></div>`).join(''):'<p style="color:var(--muted)">No records yet. Complete an assessment or enroll in a course.</p>'}</div>`}
function coursesPage(){return header('Learn and grow','Course marketplace','Live classes, recorded courses and notes/resources in one place.')+`<div class="grid content-grid"><div class="grid">${courses.map(c=>`<div class="card"><div class="card-heading"><h3>${c.title}</h3><span class="tag">${c.price===0?'FREE':'₹'+c.price}</span></div><div style="display:flex;gap:8px;flex-wrap:wrap;margin:8px 0 12px"><span class="pill">${c.mode}</span><span class="tag">${c.level}</span><span class="tag">${c.duration}</span></div><p style="color:var(--muted);line-height:1.5">${c.description}</p><p><strong>Access:</strong> <span style="color:var(--muted)">${c.access}</span></p><div style="display:flex;gap:8px;flex-wrap:wrap;margin:14px 0">${c.skills.map(s=>`<span class="tag">${s}</span>`).join('')}</div><small style="color:var(--muted)">Certificate included · Notes available</small><br/><button class="secondary course-notes" data-course="${c.id}" style="margin-top:14px">View notes</button> <button class="primary course-buy" data-course="${c.id}" style="margin-top:14px">${c.price===0?'Enroll free':'Buy and enroll'} →</button></div>`).join('')}</div><div class="card"><div class="card-heading"><h3>My enrollments</h3></div>${state.enrollments.length?state.enrollments.map(e=>`<div class="task"><div><p>${e.title}</p><small>${e.status} · ${e.transactionId}</small></div><span class="tag">${e.progress}%</span></div>`).join(''):'<p style="color:var(--muted)">No course enrollment yet.</p>'}</div></div>`+(state.selectedCourse?paymentModal(courseById(state.selectedCourse)):'')+(state.selectedNotes?notesModal(courseById(state.selectedNotes)):'')}
function notesModal(c){return `<div class="modal-backdrop"><div class="card payment-modal"><div class="card-heading"><h3>${c.title} · Notes</h3><button class="icon-btn" id="close-notes">×</button></div><p style="color:var(--muted)">${c.mode} course · ${c.access}</p><div class="roadmap">${c.notes.map((n,i)=>`<div class="roadmap-item"><div class="check">${i+1}</div><div><strong>${n}</strong><small>Downloadable learning resource</small></div><span class="tag">PDF</span></div>`).join('')}</div><button class="primary" id="save-notes" style="margin-top:16px">Save notes to my records</button></div></div>`}
function paymentModal(c){return `<div class="modal-backdrop" id="payment-modal"><div class="card payment-modal"><div class="card-heading"><h3>${c.price===0?'Free enrollment':'Buy & enroll'}: ${c.title}</h3><button class="icon-btn" id="close-payment">×</button></div><div style="display:flex;gap:8px;flex-wrap:wrap"><span class="pill">${c.mode}</span><span class="tag">${c.access}</span></div><p style="color:var(--muted)">${c.outcome}</p><div class="result"><strong>${c.price===0?'No payment required':'Total payable: ₹'+c.price}</strong><br/>${c.price===0?'Start learning immediately.':'Select UPI, debit/credit card or net banking.'}</div><form id="payment-form" class="form-grid">${c.price===0?'':`<div class="field full"><label>Payment method</label><select id="payment-method"><option>UPI</option><option>Debit/Credit Card</option><option>Net Banking</option></select></div><div class="field full"><label>UPI ID or payment reference</label><input id="payment-reference" placeholder="example@upi or card reference" required /></div>`}<div class="field full"><button class="primary" type="submit">${c.price===0?'Enroll free':'Continue to payment and enroll'}</button></div></form><small style="color:var(--muted)">${c.price===0?'Free course enrollment is active.':'Demo checkout is active. Connect Razorpay/Stripe keys for real payment verification.'}</small></div></div>`}
function aiPage(){return header('Always-on guidance','AI support','Ask about your roadmap, skill gaps, projects, interviews or courses.')+`<div class="card form-card"><div id="ai-thread" class="result" style="min-height:130px"><strong>CodeVenjar AI:</strong><br/>Hi Abhi. I know your ${state.goal} goal and can help you choose the next best action.</div><form id="ai-form" class="form-grid" style="margin-top:16px"><div class="field full"><label>Your question</label><textarea id="ai-question" rows="3" placeholder="Example: What should I learn this week to become job-ready?"></textarea></div><div class="field full"><button class="primary" type="submit">Ask CodeVenjar AI ✦</button></div></form></div>`}
function now(){return new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Kolkata'}))}
function dateText(){return new Intl.DateTimeFormat('en-IN',{weekday:'long',day:'numeric',month:'long',year:'numeric',timeZone:'Asia/Kolkata'}).format(new Date())}
function greeting(){const h=now().getHours();return h<12?'Good morning':h<17?'Good afternoon':'Good evening'}
function shell(content){app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="mark">CV</div><div><strong>CodeVenjar</strong><small>AI career copilot</small></div></div><nav class="nav">${nav.map(n=>`<button class="${state.page===n[0]?'active':''}" data-page="${n[0]}">${n[1]}&nbsp;&nbsp;${n[2]}</button>`).join('')}</nav><div class="profile-mini"><div class="mini-row"><div class="avatar">AK</div><div><strong>Abhi Kumar</strong><small style="display:block;color:var(--muted)">${state.status} · ${state.userId}</small></div></div><p>Keep building. Your next opportunity is one project away.</p></div></aside><main class="main">${content}</main></div>`;document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;render()})}
function header(kicker,title,subtitle,action=''){return `<div class="topbar"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="top-actions">${action}</div></div>`}
function planFor(goal=state.goal,skills=state.skills,hours=state.hours,project=state.project){const t=templates[goal]||templates['Data Analyst'];const ordered=t.skills.map(k=>[k,Number(skills[k]??0)]).sort((a,b)=>a[1]-b[1]);const gaps=ordered.filter(x=>x[1]<70);const focus=gaps.length?gaps.slice(0,3).map(x=>x[0]):[ordered[0]?.[0]||t.skills[0]];const multiplier=hours==='10+ hours'?1.7:hours==='6–10 hours'?1.3:1;const weeks=Math.max(4,Math.round(8/multiplier));const items=[['Foundation & gap repair',`Learn ${focus[0]} through a focused beginner-to-intermediate module`,`${Math.min(100,Math.round((100-(ordered[0]?.[1]||0))*0.8))}% gap`],['Guided practice',`Complete 3 practical ${focus.slice(0,2).join(' + ')} challenges`,`${Math.max(2,Math.round(weeks/3))} weeks`],['Build your project',project?`Build: ${project}`:`Ship a ${goal} portfolio project`,hours],['Portfolio & proof','Write a case study, publish your work and prepare an interview story','Job-ready']];return {goal,hours,project,focus,weeks,items,projects:t.projects,createdAt:new Date().toISOString()}}
function overview(){return header(dateText().toUpperCase(),`${greeting()}, Abhi.`,`Live time: <span id="live-time">${now().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:true,timeZone:'Asia/Kolkata'})}</span> · Let’s turn your learning time into visible career progress.`,`<button class="secondary" data-page="assessment">Update my skills</button>`)+`<section class="grid hero-grid"><div class="card hero"><span class="pill">✦ AI CAREER CO-PILOT</span><h2>From beginner to job-ready, one clear step at a time.</h2><p>Your ${state.goal} journey is shaped around your current skills and the gaps that matter most for your target role.</p><button class="primary" data-page="roadmap">Continue journey →</button></div><div class="card goal-card"><div><span class="eyebrow">Current target</span><h3>${state.goal}</h3><p>${state.plan?.focus?.length?`Priority gaps: ${state.plan.focus.join(', ')}.`:'Complete your assessment to calculate your priority gaps.'}</p></div><div><div class="progress-ring"></div><div style="text-align:center;color:var(--muted);font-size:13px">Journey progress</div></div></div></section><section class="grid stats">${[['Skills mapped',String(Object.keys(state.skills).length).padStart(2,'0'),'Live profile'],['Weekly time',state.hours,'Your availability'],['Projects shipped','01','Keep going'],['Career match',state.plan?'Personalized':'82%','Based on profile']].map(x=>`<div class="card stat"><span class="label">${x[0]}</span><strong>${x[1]}</strong><span class="delta">${x[2]}</span></div>`).join('')}</section><section class="grid content-grid"><div class="card"><div class="card-heading"><h3>Your skill snapshot</h3><button class="link" data-page="assessment">Edit skills</button></div><div class="skills">${Object.entries(state.skills).map(([k,v])=>`<div class="skill-row"><span>${k}</span><div class="bar"><i style="width:${v}%"></i></div><b>${v}</b></div>`).join('')}</div></div><div class="card"><div class="card-heading"><h3>This week’s focus</h3><span class="tag">${state.plan?.focus?.length||3} gaps</span></div>${(state.plan?.focus||['SQL','Storytelling','Portfolio']).slice(0,3).map((x,i)=>`<div class="task"><div><p>${i===0?'Start':'Practice'} ${x}</p><small>${i===0?'25 min':'30 min'} · Priority gap</small></div><button class="icon-btn task-done">✓</button></div>`).join('')}</div></section>`}
function assessment(){const t=templates[state.goal]||templates['Data Analyst'];const skillFields=t.skills.map(k=>`<div class="field"><label>${k} confidence (0–100)</label><input type="number" min="0" max="100" value="${state.skills[k]??50}" data-skill="${k}" required /></div>`).join('');return header('Personalize your path','Skill assessment','Your answers control the roadmap. Change them anytime to regenerate a better plan.')+`<div class="card form-card"><form id="assessment-form" class="form-grid"><div class="field"><label>Target career</label><select id="goal">${Object.keys(templates).map(g=>`<option ${state.goal===g?'selected':''}>${g}</option>`).join('')}</select></div><div class="field"><label>Hours available per week</label><select id="hours"><option ${state.hours==='3–5 hours'?'selected':''}>3–5 hours</option><option ${state.hours==='6–10 hours'?'selected':''}>6–10 hours</option><option ${state.hours==='10+ hours'?'selected':''}>10+ hours</option></select></div>${skillFields}<div class="field full"><label>What do you want to build?</label><textarea id="project" rows="3" placeholder="Example: an internship-ready sales analytics dashboard">${state.project||''}</textarea></div><div class="field full"><button class="primary" type="submit">Generate my personalized roadmap ✦</button></div></form><div id="assessment-result" class="result hidden"></div></div>`}
function roadmapPage(){const p=state.plan||planFor();return header('Your next best steps','My roadmap',`Generated for ${p.goal} · ${p.hours} · ${p.weeks}-week suggested journey`,`<button class="primary" data-page="assessment">Regenerate roadmap</button>`)+`<div class="grid content-grid"><div class="card"><div class="card-heading"><h3>${p.goal} journey</h3><span class="pill">Live plan</span></div><p style="color:var(--muted);line-height:1.6">This plan is not a generic list. It starts with your lowest-scoring skills (<strong style="color:var(--text)">${p.focus.join(', ')}</strong>), fits your weekly availability and ends with a portfolio project you can show to recruiters.</p><div class="roadmap">${p.items.map((r,i)=>`<div class="roadmap-item"><div class="check ${i?'pending':''}">${i?'○':'✓'}</div><div><strong>Week ${i+1}: ${r[0]}</strong><small>${r[1]}</small><small><strong>Why this matters:</strong> ${i===0?'It closes your biggest skill gap.':i===1?'Practice converts lessons into repeatable ability.':i===2?'A shipped project becomes proof of work.':'A case study helps recruiters understand your impact.'}</small></div><span class="tag">${r[2]}</span></div>`).join('')}</div></div><div class="card"><div class="card-heading"><h3>Recommended projects</h3></div>${p.projects.map(x=>`<div class="task"><div><p>${x[0]}</p><small>${x[1]}</small></div><span class="tag">${x[2]}</span></div>`).join('')}<button class="secondary" data-page="assignments" style="margin-top:14px">Open related assignments →</button></div></div>`}
function simplePage(type){const data={mentors:['Mentor network','Learn with people who have already made the leap.','Office hours matched to your '+state.goal+' journey.'],portfolio:['Your portfolio','Make your progress easy to show.','A clean profile is ready for your first case study.']}[type];return header(type==='mentors'?'Connect & lead':'Proof of work',data[0],data[2])+`<div class="card"><span class="pill">${type==='mentors'?'MENTOR MATCH':'PORTFOLIO PROFILE'}</span><h2 style="font:700 27px 'Space Grotesk';margin:18px 0 8px">${data[1]}</h2><p style="color:var(--muted);max-width:620px;line-height:1.6">${type==='mentors'?'Based on your goals, we found practitioners who can help you move from learning concepts to shipping work.':'Your public profile will collect your skill snapshot, roadmap wins and finished projects in one shareable place.'}</p><button class="primary" onclick="toast('${type==='mentors'?'Mentor matching is ready for the next sprint.':'Portfolio profile created in demo mode.'}')">${type==='mentors'?'Explore mentors':'Preview portfolio'} →</button></div>`}
function render(){const pages={overview,assessment,roadmap:roadmapPage,courses:coursesPage,records:recordsPage,status:statusPage,ai:aiPage,assignments:assignmentsPage,mentors:mentorPage,portfolio:portfolioPage};shell(`<div class="page">${pages[state.page]()}</div>`);const form=document.querySelector('#assessment-form');if(form){form.querySelector('#goal').onchange=()=>{state.goal=form.querySelector('#goal').value;render()};form.onsubmit=e=>{e.preventDefault();const goal=document.querySelector('#goal').value;const skills={};templates[goal].skills.forEach(k=>skills[k]=Number(document.querySelector(`[data-skill="${k}"]`)?.value||50));state.goal=goal;state.hours=document.querySelector('#hours').value;state.project=document.querySelector('#project').value.trim();state.skills=skills;state.plan=planFor(goal,skills,state.hours,state.project);state.status='Learning';addRecord('Assessment','Skill assessment updated',`${goal} · ${state.hours}`);const result=document.querySelector('#assessment-result');result.classList.remove('hidden');result.innerHTML=`<strong>Roadmap generated successfully for ${goal} ✦</strong><br/>Your priority gaps are <b>${state.plan.focus.join(', ')}</b>. The plan is based on ${state.hours} per week and your project requirement. <button class="link" data-page="roadmap">Open roadmap →</button>`;result.querySelector('[data-page]').onclick=()=>{state.page='roadmap';render()};toast('Personalized roadmap updated')}}
document.querySelectorAll('.course-buy').forEach(b=>b.onclick=()=>{state.selectedCourse=b.dataset.course;render()});const close=document.querySelector('#close-payment');if(close)close.onclick=()=>{state.selectedCourse=null;render()};const payment=document.querySelector('#payment-form');if(payment)payment.onsubmit=e=>{e.preventDefault();const c=courseById(state.selectedCourse);const method=document.querySelector('#payment-method').value;const transactionId=`TXN-${Date.now()}`;state.enrollments.unshift({courseId:c.id,title:c.title,status:'Enrolled',progress:0,transactionId});state.payments.unshift({transactionId,courseId:c.id,amount:c.price,method,status:'Demo paid',at:new Date().toISOString()});state.status='Enrolled';state.selectedCourse=null;addRecord('Enrollment',`Enrolled in ${c.title}`,`₹${c.price} · ${method} · ${transactionId}`);toast('Payment recorded and course enrolled');render()};const aiForm=document.querySelector('#ai-form');if(aiForm)aiForm.onsubmit=e=>{e.preventDefault();const q=document.querySelector('#ai-question').value.trim();if(!q)return;const focus=state.plan?.focus?.join(', ')||'your skill assessment';const answer=`Based on your ${state.goal} goal, focus on ${focus}. Start with one practical task today, save the result in your records, and use the recommended course only if it matches your current gap.`;state.aiMessages.push({q,answer,at:new Date().toISOString()});addRecord('AI support','Asked CodeVenjar AI',q.slice(0,80));document.querySelector('#ai-thread').innerHTML=`<strong>You:</strong><br/>${q}<br/><br/><strong>CodeVenjar AI:</strong><br/>${answer}`;document.querySelector('#ai-question').value='';toast('AI guidance generated')}}
function wireFeatureEvents(){document.querySelectorAll('.course-buy').forEach(b=>b.onclick=()=>{state.selectedCourse=b.dataset.course;render()});document.querySelectorAll('.course-notes').forEach(b=>b.onclick=()=>{state.selectedNotes=b.dataset.course;render()});const closeNotes=document.querySelector('#close-notes');if(closeNotes)closeNotes.onclick=()=>{state.selectedNotes=null;render()};const saveNotes=document.querySelector('#save-notes');if(saveNotes)saveNotes.onclick=()=>{const c=courseById(state.selectedNotes);state.selectedNotes=null;addRecord('Course notes',`Saved notes for ${c.title}`,c.mode);toast('Course notes saved to records');render()};const closePayment=document.querySelector('#close-payment');if(closePayment)closePayment.onclick=()=>{state.selectedCourse=null;render()};const payment=document.querySelector('#payment-form');if(payment)payment.onsubmit=e=>{e.preventDefault();const c=courseById(state.selectedCourse);const method=c.price===0?'Free enrollment':document.querySelector('#payment-method').value;const ref=c.price===0?'FREE-'+Date.now():(document.querySelector('#payment-reference')?.value||'demo-reference');const transactionId=`TXN-${Date.now()}`;state.enrollments.unshift({courseId:c.id,title:c.title,mode:c.mode,status:'Enrolled',progress:0,transactionId});state.payments.unshift({transactionId,courseId:c.id,amount:c.price,method,reference:ref,status:c.price===0?'Free enrolled':'Demo paid',at:new Date().toISOString()});state.status='Enrolled';state.selectedCourse=null;addRecord('Enrollment',`Enrolled in ${c.title}`,`${c.mode} · ${c.price===0?'Free':'₹'+c.price} · ${method} · ${transactionId}`);toast(c.price===0?'Free course enrolled':'Payment recorded and course enrolled');render()};document.querySelectorAll('.mentor-book').forEach(b=>b.onclick=()=>{state.selectedMentor=b.dataset.mentor;render()});const closeMentor=document.querySelector('#close-mentor');if(closeMentor)closeMentor.onclick=()=>{state.selectedMentor=null;render()};const mentorForm=document.querySelector('#mentor-form');if(mentorForm)mentorForm.onsubmit=e=>{e.preventDefault();const m=mentors.find(x=>x.id===state.selectedMentor);const slot=document.querySelector('#mentor-slot').value;state.mentorBookings=state.mentorBookings||[];state.mentorBookings.unshift({mentor:m.name,slot,status:'Confirmed',note:document.querySelector('#mentor-note').value});state.selectedMentor=null;addRecord('Mentor booking',`Booked ${m.name}`,slot);toast('Mentor session booked');render()};document.querySelectorAll('.assignment-done').forEach(b=>b.onclick=()=>{const a=assignments.find(x=>x.id===b.dataset.assignment);a.done=true;addRecord('Assignment',`Completed ${a.title}`,a.topic);toast('Assignment completed');render()});const portfolioForm=document.querySelector('#portfolio-form');if(portfolioForm)portfolioForm.onsubmit=e=>{e.preventDefault();state.portfolio={name:document.querySelector('#profile-name').value,headline:document.querySelector('#profile-headline').value,bio:document.querySelector('#profile-bio').value,location:document.querySelector('#profile-location').value,project:document.querySelector('#profile-project').value,skills:Object.keys(state.skills).join(' · ')};addRecord('Portfolio','Profile updated',state.portfolio.project);toast('Portfolio profile saved');render()}}
function updateClock(){const el=document.querySelector('#live-time');if(el)el.textContent=now().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:true,timeZone:'Asia/Kolkata'})}
function toast(message){const t=document.createElement('div');t.className='toast';t.textContent=message;document.body.append(t);setTimeout(()=>t.remove(),2600)}
const baseRender=render;render=function(){baseRender();wireFeatureEvents()};render();setInterval(updateClock,1000);
